import json
from pathlib import Path
m = json.loads(Path("outputs/metrics.json").read_text())
store = {}
for start, met in m["backtest"].items():
    store[start] = {"baseline": met}
tgt = next(x for x in m["target_week"] if x["label"] == "LightGBM")
store[m["target_week_start"][:10]] = {"baseline": tgt}
Path("outputs/experiment_bridge.json").write_text(json.dumps(store, indent=2) + "\n")
for k, v in store.items():
    print(k, "baseline MAPE", round(v["baseline"]["mape_pct"], 2))
